import itertools

fixed_edges = [(0,6), (1,10), (3,6), (3,8), (2,7), (0,4), (1,6), (0,8), (1,2), (5,10), (0,3)]
n = 11

adj = {i: set() for i in range(n)}
for u,v in fixed_edges:
    adj[u].add(v)
    adj[v].add(u)

# Compute independence number via brute force (2^11 = 2048, easy)
max_ind_set = []
max_ind_size = 0
for mask in range(1<<n):
    # check if independent
    ok = True
    for u in range(n):
        if not (mask>>u & 1):
            continue
        for v in adj[u]:
            if mask>>v & 1:
                ok = False
                break
        if not ok:
            break
    if ok:
        size = bin(mask).count('1')
        if size > max_ind_size:
            max_ind_size = size
            max_ind_set = [i for i in range(n) if mask>>i & 1]

print("Current independence number:", max_ind_size)
print("Max independent set:", max_ind_set)

# Compute vertex connectivity (minimum vertex cut size)
# For small n, we can brute force all subsets of vertices to remove and check if graph becomes disconnected.
# Vertex connectivity = min size of vertex cut that disconnects the graph (or reduces to single vertex).
# For complete graph, it's n-1.

def is_connected(adj, removed):
    # BFS
    start = None
    for v in range(n):
        if v not in removed:
            start = v
            break
    if start is None:
        return True  # empty graph considered connected? Actually no vertices left.
    visited = set([start])
    stack = [start]
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if v not in removed and v not in visited:
                visited.add(v)
                stack.append(v)
    # Check if all non-removed vertices are visited
    for v in range(n):
        if v not in removed and v not in visited:
            return False
    return True

min_cut = n
for r in range(n+1):
    for removed in itertools.combinations(range(n), r):
        if not is_connected(adj, set(removed)):
            min_cut = min(min_cut, r)
            break
    if min_cut < n:
        break

print("Vertex connectivity:", min_cut)

