import itertools

n = 11
fixed_edges = [(0,6), (1,10), (3,6), (3,8), (2,7), (0,4), (1,6), (0,8), (1,2), (5,10), (0,3)]

all_edges = [(i,j) for i in range(n) for j in range(i+1,n)]
fixed_set = set(fixed_edges)
variable_edges = [e for e in all_edges if e not in fixed_set]
edge_to_var = {e: i+1 for i, e in enumerate(variable_edges)}
var_to_edge = {i+1: e for i, e in enumerate(variable_edges)}
num_vars = len(variable_edges)
print("Number of variable edges:", num_vars)

cnf = CNF()

# Alpha <= 4: for each 5-set, at least one edge
five_sets = list(itertools.combinations(range(n), 5))
print("Number of 5-sets:", len(five_sets))

for S in five_sets:
    clause = []
    for u, v in itertools.combinations(S, 2):
        if (u,v) in fixed_set or (v,u) in fixed_set:
            clause = None
            break
        else:
            clause.append(edge_to_var[(u,v)])
    if clause is not None:
        cnf.append(clause)

print("Number of clauses:", len(cnf.clauses))

# Solve
with Solver(bootstrap_with=cnf) as solver:
    status = solver.solve()
    if status:
        model = solver.get_model()
        print("SAT")
        extra_edges = []
