                        ok = False
                        break
                if not ok:
                    break
            if ok:
                sz = bin(mask).count('1')
                if sz > max_ind:
                    max_ind = sz
        print("Independence number:", max_ind)

        # Check vertex connectivity
        def is_connected(adj, removed):
            start = None
            for v in range(n):
                if v not in removed:
                    start = v
                    break
            if start is None:
                return True
            visited = set([start])
            stack = [start]
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if v not in removed and v not in visited:
                        visited.add(v)
                        stack.append(v)
            for v in range(n):
                if v not in removed and v not in visited:
